//! R4 H0 differential correctness suite (task contract §19–§22).
//!
//! The judge for every case is the frozen gate:
//!
//! ```text
//! incremental result == clean authoritative parse
//! ```
//!
//! applied structurally (full normalized-tree equality) AND by the
//! deterministic checksum, over CORPUS-v1 corpora generated by the
//! reference generator. Structural equality with the clean parse of the
//! SAME bytes is a consistency oracle, not an independent proof of
//! grammar conformance — grammar conformance is established by the 43
//! golden fixtures (tests/fixtures.rs). Together they are the H0 gate.

use markit_mdbench_common::source::SourceId;
use markit_mdbench_common::CanonicalEdit;
use markit_mdbench_common::CounterSink;
use markit_mdbench_common::Mechanism;
use markit_mdbench_common::MechanismContext;
use markit_mdbench_common::Observed;
use markit_mdbench_common::ResultChecksum;
use markit_mdbench_common::Source;
use markit_mdbench_common::WorkCounters;
use markit_mdbench_corpusgen as gen;
use markit_mdbench_corpusgen::mutations::{
    generic_edit, query_anchors, structural_edit_for, AnchorClass, EditSize, GenericOp, Recipe,
};
use markit_mdbench_full_rebuild as h0;
use markit_mdbench_full_rebuild::FullRebuildMechanism;
use markit_mdbench_oracle::normalized::{
    node_path_at, normalized_checksum, Node, NodeKind, NormalizedDocument,
};
use markit_mdbench_oracle::validate_root;

use gen::{PayloadShape, ALL_SHAPES, SIZE_16M, SIZE_1M, SIZE_64K};

// ---------------------------------------------------------------------------
// Harness
// ---------------------------------------------------------------------------

fn source_of(bytes: &[u8], id: u64) -> Source {
    Source::new(
        SourceId(id),
        String::from_utf8(bytes.to_vec()).expect("corpus is UTF-8"),
    )
}

fn canon(edit: &gen::mutations::PlannedEdit) -> CanonicalEdit {
    CanonicalEdit::new(
        edit.start,
        edit.end,
        String::from_utf8(edit.inserted.clone()).expect("insertion is ASCII"),
    )
    .expect("edit in range")
}

/// FULL_PARSE through the mechanism with its OWN counter stream; returns
/// the sealed state.
fn mech_full_parse(bytes: &[u8]) -> h0::H0State {
    let mut counters = WorkCounters::all_unknown();
    let mut sink = CounterSink::new(&mut counters);
    let mut cx = MechanismContext::new(&mut sink);
    let mech = FullRebuildMechanism::new();
    let source = source_of(bytes, 1);
    let pending = mech.full_parse(&source, &mut cx).expect("full_parse");
    mech.complete(pending).expect("complete").state
}

/// The frozen differential gate: run H0's update path from `old_state`
/// and require `result == clean authoritative parse` of the post source,
/// structurally and by checksum. Returns the new state plus the UPDATE
/// phase's own counters (the initial parse used a separate stream).
fn assert_update_differential(
    old: &[u8],
    post: &[u8],
    edit: &CanonicalEdit,
    old_state: h0::H0State,
    context: &str,
) -> (h0::H0State, WorkCounters) {
    let mut counters = WorkCounters::all_unknown();
    let new_state;
    {
        let mut sink = CounterSink::new(&mut counters);
        let mut cx = MechanismContext::new(&mut sink);
        let mech = FullRebuildMechanism::new();
        let old_source = source_of(old, 10);
        let post_source = source_of(post, 11);
        let prepared = mech
            .prepare_update(&old_source, &post_source, edit, &old_state, &mut cx)
            .expect("prepare_update");
        let pending = mech
            .update(
                &old_source,
                &post_source,
                edit,
                old_state,
                prepared,
                &mut cx,
            )
            .expect("update");
        let done = mech.complete(pending).expect("complete");
        let clean = h0::parse_document(post);
        assert_eq!(
            done.state.document, clean,
            "structural mismatch ({context})"
        );
        assert_eq!(
            done.state.result_checksum(),
            normalized_checksum(&clean),
            "checksum mismatch ({context})"
        );
        assert_eq!(done.state.source_len_bytes, post.len(), "{context}");
        new_state = done.state;
    }
    (new_state, counters)
}

/// Tree invariants (NORMALIZED-RESULT-v1): enforced by the ONE shared
/// conformance gate in the oracle crate (R4-H0-REFERENCE-CORRECTIVE-1) —
/// exact field-kind legality, `start < end` for every node, the
/// `FencedCode.content` interval rule (empty legal), parent containment,
/// sibling order, UTF-8 char boundaries, Document == [0, len).
fn validate_tree(node: &Node, src: &[u8]) {
    if let Err(e) = validate_root(node, Some(src)) {
        panic!("normalized tree violates NORMALIZED-RESULT-v1: {e}");
    }
}

fn validated_clean(src: &[u8]) -> NormalizedDocument {
    let doc = h0::parse_document(src);
    validate_tree(&doc.root, src);
    doc
}

/// (blocks, all-nodes) counts of a parse product, mirroring the
/// mechanism's attribution classifier (block kinds = the 7 block kinds;
/// the Document root is not a parse product).
fn count_blocks_nodes(root: &Node) -> (u64, u64) {
    const INLINE: [NodeKind; 5] = [
        NodeKind::Text,
        NodeKind::Emphasis,
        NodeKind::CodeSpan,
        NodeKind::Link,
        NodeKind::ReferenceLink,
    ];
    fn walk(n: &Node, blocks: &mut u64, nodes: &mut u64) {
        *nodes += 1;
        if !INLINE.contains(&n.kind) {
            *blocks += 1;
        }
        for c in &n.children {
            walk(c, blocks, nodes);
        }
    }
    let mut blocks = 0;
    let mut nodes = 0;
    walk(root, &mut blocks, &mut nodes);
    (blocks - 1, nodes - 1)
}

// ---------------------------------------------------------------------------
// FULL_PARSE differential: every corpus, clean parse == mechanism result
// ---------------------------------------------------------------------------

#[test]
fn full_parse_matches_mechanism_result_on_all_corpora() {
    for shape in ALL_SHAPES {
        for size in [SIZE_64K, SIZE_1M] {
            let bytes = gen::generate(shape, size).expect("generate");
            let clean = validated_clean(&bytes);
            let state = mech_full_parse(&bytes);
            assert_eq!(state.document, clean, "{shape:?}-{size}");
            assert_eq!(state.source_len_bytes, size);
        }
    }
}

#[test]
fn full_parse_is_deterministic_and_matches_on_the_top_size() {
    for shape in [
        PayloadShape::Plain,
        PayloadShape::DeepContainer,
        PayloadShape::ReferenceFanout,
    ] {
        let bytes = gen::generate(shape, SIZE_16M).expect("generate");
        let clean = validated_clean(&bytes);
        let state = mech_full_parse(&bytes);
        assert_eq!(state.document, clean, "{shape:?}-16m");
        // double-parse determinism at the top size
        let again = mech_full_parse(&bytes);
        assert_eq!(state, again, "{shape:?}-16m: nondeterministic");
    }
    // double-parse determinism across all shapes at 64k
    for shape in ALL_SHAPES {
        let bytes = gen::generate(shape, SIZE_64K).expect("generate");
        assert_eq!(mech_full_parse(&bytes), mech_full_parse(&bytes));
    }
}

// ---------------------------------------------------------------------------
// UPDATE differential — generic edit grid (CASE-MATRIX Blocks A/B/C)
// ---------------------------------------------------------------------------

fn generic_grid_case(
    shape: PayloadShape,
    size: usize,
    class: AnchorClass,
    es: EditSize,
    op: GenericOp,
) {
    let old = gen::generate(shape, size).expect("generate");
    let clean_old = validated_clean(&old);
    let old_state = mech_full_parse(&old);
    assert_eq!(old_state.document, clean_old);

    let edit = generic_edit(&old, class, es, op);
    let post = gen::mutations::apply(&old, &edit);
    gen::mutations::validate(&old, &edit, &post).expect("frozen mutation invariants");

    let context = format!(
        "{:?}-{} {:?} {:?} {:?} @{}",
        shape,
        gen::size_label(size),
        class,
        es,
        op,
        edit.start
    );
    let (new_state, _) =
        assert_update_differential(&old, &post, &canon(&edit), old_state, &context);
    validate_tree(&new_state.document.root, &post);
}

#[test]
fn update_matches_clean_parse_generic_grid_64k() {
    // Block B grid on the three structurally distinct payloads: full
    // 5 ops x 3 edit sizes x 3 anchors at 64k for suite speed.
    for shape in [
        PayloadShape::Plain,
        PayloadShape::FenceHeavy,
        PayloadShape::Mixed,
    ] {
        for class in [AnchorClass::Early, AnchorClass::Middle, AnchorClass::Late] {
            for es in [EditSize::Tiny, EditSize::Small, EditSize::Medium] {
                for op in [
                    GenericOp::Insert,
                    GenericOp::Delete,
                    GenericOp::ReplaceEq,
                    GenericOp::ReplaceGrow,
                    GenericOp::ReplaceShrink,
                ] {
                    generic_grid_case(shape, SIZE_64K, class, es, op);
                }
            }
        }
    }
}

