// ---------------------------------------------------------------------------
// UPDATE differential — structural recipes (CASE-MATRIX Block D)
// ---------------------------------------------------------------------------

#[test]
fn update_matches_clean_parse_structural_recipes_64k() {
    // Every applicable (shape, recipe) pair at 64k, at the recipe's
    // frozen selection anchor; FsFenceOpen takes both EARLY and MIDDLE
    // variants (the frozen two-case probe).
    for shape in ALL_SHAPES {
        let old = gen::generate(shape, SIZE_64K).expect("generate");
        for recipe in gen::mutations::ALL_RECIPES {
            let anchors: &[AnchorClass] = if recipe == Recipe::FsFenceOpen {
                &[AnchorClass::Early, AnchorClass::Middle]
            } else {
                &[recipe.selection_anchor()]
            };
            for &class in anchors {
                let Ok(edit) = structural_edit_for(&old, recipe, class, shape, SIZE_64K) else {
                    continue; // declared NOT_APPLICABLE: recorded by the generator gate
                };
                let post = gen::mutations::apply(&old, &edit);
                gen::mutations::validate(&old, &edit, &post).expect("frozen mutation invariants");
                let old_state = mech_full_parse(&old);
                let context = format!("{shape:?}-64k {} {class:?}", recipe.id());
                let (new_state, _) =
                    assert_update_differential(&old, &post, &canon(&edit), old_state, &context);
                validate_tree(&new_state.document.root, &post);
            }
        }
    }
}

#[test]
fn update_matches_clean_parse_structural_recipes_1m() {
    // The semantic-dependency and forward-state probes at 1m: fanout
    // damage and fence-move damage over full-size documents.
    for (shape, recipes) in [
        (
            PayloadShape::ReferenceFanout,
            &[
                Recipe::SdDefReplace,
                Recipe::SdDefDelete,
                Recipe::IdsLinkDelim,
            ] as &[Recipe],
        ),
        (
            PayloadShape::FenceHeavy,
            &[Recipe::FsFenceClose, Recipe::LocUtf8Swap] as &[Recipe],
        ),
        (
            PayloadShape::Mixed,
            &[
                Recipe::SdDefReplace,
                Recipe::FsFenceClose,
                Recipe::CsItemIndent,
            ] as &[Recipe],
        ),
        (
            PayloadShape::DeepContainer,
            &[Recipe::CsBqNestLine, Recipe::BbParaSplit] as &[Recipe],
        ),
    ] {
        let old = gen::generate(shape, SIZE_1M).expect("generate");
        for &recipe in recipes {
            let edit = structural_edit_for(&old, recipe, recipe.selection_anchor(), shape, SIZE_1M)
                .unwrap_or_else(|na| panic!("{} on {shape:?}-1m: {na:?}", recipe.id()));
            let post = gen::mutations::apply(&old, &edit);
            let old_state = mech_full_parse(&old);
            let context = format!("{shape:?}-1m {}", recipe.id());
            assert_update_differential(&old, &post, &canon(&edit), old_state, &context);
        }
    }
}

// ---------------------------------------------------------------------------
// Old-state independence (H0 never reuses old state)
// ---------------------------------------------------------------------------

#[test]
fn update_result_is_independent_of_the_old_state() {
    let old = gen::generate(PayloadShape::Mixed, SIZE_64K).expect("generate");
    let edit = generic_edit(
        &old,
        AnchorClass::Middle,
        EditSize::Small,
        GenericOp::ReplaceEq,
    );
    let post = gen::mutations::apply(&old, &edit);
    let canonical = canon(&edit);

    // Three DIFFERENT old states — the true one, a state parsed from an
    // unrelated corpus, and a deliberately corrupted one — must all
    // produce the identical (correct) update result.
    let true_state = mech_full_parse(&old);
    let unrelated = gen::generate(PayloadShape::ReferenceFanout, SIZE_64K).expect("generate");
    let unrelated_state = mech_full_parse(&unrelated);
    let mut corrupted = true_state.clone();
    corrupted.document.root.children.clear();
    corrupted.document.root.end = 0;

    let mut reference = None;
    for state in [true_state, unrelated_state, corrupted] {
        let (new_state, _) =
            assert_update_differential(&old, &post, &canonical, state, "old-state independence");
        match &reference {
            None => reference = Some(new_state),
            Some(r) => assert_eq!(&new_state, r, "old state leaked into the result"),
        }
    }
}

#[test]
fn chained_edits_stay_equal_to_clean_parses() {
    // A chain of edits, each update re-based on the previous state, must
    // match the clean parse at EVERY step (revision chain).
    let mut current = gen::generate(PayloadShape::Plain, SIZE_64K).expect("generate");
    let mut state = mech_full_parse(&current);
    let ops = [
        (AnchorClass::Early, EditSize::Tiny, GenericOp::Insert),
        (AnchorClass::Middle, EditSize::Small, GenericOp::ReplaceGrow),
        (AnchorClass::Late, EditSize::Tiny, GenericOp::Delete),
        (AnchorClass::Middle, EditSize::Tiny, GenericOp::Insert),
    ];
    for (i, (class, es, op)) in ops.into_iter().enumerate() {
        let edit = generic_edit(&current, class, es, op);
        let post = gen::mutations::apply(&current, &edit);
        let context = format!("chain step {i}");
        let (next, _) = assert_update_differential(&current, &post, &canon(&edit), state, &context);
        state = next;
        current = post;
    }
}

// ---------------------------------------------------------------------------
// QUERY — NODE_PATH_AT ordered batch (NORMALIZED-RESULT-v1 §4)
// ---------------------------------------------------------------------------

#[test]
fn query_batch_matches_the_frozen_contract() {
    // QUERY = ONE ordered batch of three NODE_PATH_AT subqueries at the
    // generic EARLY/MIDDLE/LATE anchors over the INITIAL state. The
    // answering function is defined over the normalized tree alone (its
    // signature takes no source and no parser), so it cannot reparse.
    for shape in ALL_SHAPES {
        let bytes = gen::generate(shape, SIZE_64K).expect("generate");
        let state = mech_full_parse(&bytes);
        let [early, middle, late] = query_anchors(&bytes);
        for (offset, label) in [(early, "EARLY"), (middle, "MIDDLE"), (late, "LATE")] {
            let path = node_path_at(&state.document, offset);
            assert!(!path.is_empty(), "{shape:?} {label}");
            assert_eq!(path[0].kind, NodeKind::Document);
            assert_eq!((path[0].start, path[0].end), (0, bytes.len()));
            for pn in &path {
                assert!(
                    pn.start <= offset && offset < pn.end,
                    "{shape:?} {label}: {:?} {}..{} does not contain {offset}",
                    pn.kind,
                    pn.start,
                    pn.end
                );
            }
            // ordered root -> leaf, nested spans. A paragraph whose only
            // inline child is one Text run shares that child's span —
            // legal; containment itself is still checked.
            for w in path.windows(2) {
                assert!(w[1].start >= w[0].start && w[1].end <= w[0].end);
            }
            // identical when re-asked (deterministic; no parse)
            assert_eq!(
                path,
                node_path_at(&state.document, offset),
                "{shape:?} {label}"
            );
            // and identical to the clean parse of the same bytes
            assert_eq!(path, node_path_at(&h0::parse_document(&bytes), offset));
        }
    }
}

#[test]
fn query_extremes_and_multibyte_boundaries() {
    let bytes = gen::generate(PayloadShape::Plain, SIZE_64K).expect("generate");
    let doc = h0::parse_document(&bytes);

    // EOF answers the single-node [Document] path (end-inclusive special
    // case)
    let eof = node_path_at(&doc, bytes.len());
    assert_eq!(eof.len(), 1);
    assert_eq!(eof[0].kind, NodeKind::Document);

    // a whitespace gap (the blank line at byte 0) answers [Document]
    let gap = node_path_at(&doc, 0);
    assert_eq!(gap.len(), 1);
    assert_eq!(gap[0].kind, NodeKind::Document);

    // char-boundary offsets inside CJK runs resolve into the holding
    // Text node: unit 0 is the CJK variant, 中文 = bytes [1, 7)
    let at = node_path_at(&doc, 3); // start of 文
    let deepest = at.last().expect("nonempty");
    assert_eq!(deepest.kind, NodeKind::Text);
    assert!(deepest.start < 3 && 3 < deepest.end);

    // byte coordinates: a mid-scalar offset still answers the containing
    // Text path (the FROZEN anchors are boundary-snapped upstream; the
    // tree contract itself is pure byte containment)
    let mid = node_path_at(&doc, 2); // inside 中
    assert_eq!(mid.last().map(|p| p.kind), Some(NodeKind::Text));

    // offsets exactly AT a node's end do NOT descend into it (half-open
    // containment): byte 63 closes unit 0's Text node, byte 64 opens
    // unit 1's blank-line gap
    let boundary = node_path_at(&doc, 63);
    assert!(boundary.last().is_none_or(|p| p.start != 1 || p.end != 63));
}

// ---------------------------------------------------------------------------
// Eager completion proof (H0_EAGER_COMPLETION_VALIDATION_PASS)
// ---------------------------------------------------------------------------

#[test]
fn h0_eager_completion_validation_pass() {
    // EAGER: `update`/`full_parse` return a Pending that ALREADY holds
    // the complete normalized document; `complete()` only seals the
    // state and derives the checksum. Proof obligations:
    //
    // (a) structurally — `complete()` takes no source and no sink, so no
    //     parse work CAN hide behind the completion boundary (the R1
    //     contract gives it no inputs to do any with), and the pending
    //     exposes the finished tree for inspection before completion;
    // (b) behaviorally — the full rebuild work counters and the complete
    //     source-inspection union are already observed after update(),
    //     BEFORE complete() is called.
    let old = gen::generate(PayloadShape::Mixed, SIZE_64K).expect("generate");
    let edit = generic_edit(&old, AnchorClass::Middle, EditSize::Tiny, GenericOp::Insert);
    let post = gen::mutations::apply(&old, &edit);
    let canonical = canon(&edit);

    let mech = FullRebuildMechanism::new();
    let old_source = source_of(&old, 20);
    let post_source = source_of(&post, 21);

    // phase 1: initial state (own counter stream, then dropped)
    let old_state = mech_full_parse(&old);

    // phase 2: the measured update
    let mut counters = WorkCounters::all_unknown();
    let pending = {
        let mut sink = CounterSink::new(&mut counters);
        let mut cx = MechanismContext::new(&mut sink);
        let prepared = mech
            .prepare_update(&old_source, &post_source, &canonical, &old_state, &mut cx)
            .expect("prepare");
        let pending = mech
            .update(
                &old_source,
                &post_source,
                &canonical,
                old_state,
                prepared,
                &mut cx,
            )
            .expect("update");
        cx.sink.finalize_derived();
        pending
    };

    // (b) work fully observed BEFORE complete():
    let clean = h0::parse_document(&post);
    let (blocks, nodes) = count_blocks_nodes(&clean.root);
    assert_eq!(counters.blocks_reparsed, Observed::Known(blocks));
    assert_eq!(counters.nodes_rebuilt, Observed::Known(nodes));
    assert_eq!(
        counters.unique_post_source_bytes,
        Observed::Known(post.len() as u64),
        "the block pass must inspect every byte of the post source"
    );

    // (a) the pending already carries the finished tree — no parse work
    // remains between update() and complete()
    let clean = h0::parse_document(&post);
    assert_eq!(
        normalized_checksum(pending.document()),
        normalized_checksum(&clean)
    );

    // complete() seals the state; the checksum is the post-timer export and
    // complete() reports nothing further
    let done = mech.complete(pending).expect("complete");
    assert_eq!(done.state.result_checksum(), normalized_checksum(&clean));
    assert_eq!(done.state.document, clean);
    assert_eq!(
        counters.blocks_reparsed,
        Observed::Known(count_blocks_nodes(&clean.root).0)
    );
}

// ---------------------------------------------------------------------------
// Attribution semantics (honest counters; NotApplicable != fake zero)
// ---------------------------------------------------------------------------

#[test]
fn attribution_is_honest_on_update() {
    let old = gen::generate(PayloadShape::Plain, SIZE_64K).expect("generate");
    let edit = generic_edit(&old, AnchorClass::Early, EditSize::Tiny, GenericOp::Insert);
    let post = gen::mutations::apply(&old, &edit);
    let canonical = canon(&edit);

    let mech = FullRebuildMechanism::new();
    let old_source = source_of(&old, 30);
    let post_source = source_of(&post, 31);
    let old_state = mech_full_parse(&old);

    let mut counters = WorkCounters::all_unknown();
    {
        let mut sink = CounterSink::new(&mut counters);
        let mut cx = MechanismContext::new(&mut sink);
        let prepared = mech
            .prepare_update(&old_source, &post_source, &canonical, &old_state, &mut cx)
            .expect("prepare");
        let pending = mech
            .update(
                &old_source,
                &post_source,
                &canonical,
                old_state,
                prepared,
                &mut cx,
            )
            .expect("update");
        // source-inspection slots derive to the complete post source
        cx.sink.finalize_derived();
        mech.complete(pending).expect("complete");
    }

    let clean = h0::parse_document(&post);
    let (blocks, nodes) = count_blocks_nodes(&clean.root);

    // Known(n) / Unknown / NotApplicable are DISTINCT. H0 rebuilt every
    // node (Known(nodes)), and reused NOTHING — the precise fact is
    // nodes_reused == 0, reported through the ordinary cumulative path
    // as a MEASURED zero (Known(0), R4-H0-REFERENCE-CORRECTIVE-1 §4),
    // NOT NotApplicable: the reuse concept exists and its measured value
    // is zero. H0 keeps no metadata records (NotApplicable), never fell
    // back (NotApplicable), and has no restart/convergence concepts
    // (NotApplicable gauges).
    assert_eq!(counters.nodes_rebuilt, Observed::Known(nodes));
    assert_eq!(counters.blocks_reparsed, Observed::Known(blocks));
    assert!(nodes > 0 && blocks > 0);
    assert_eq!(counters.nodes_reused, Observed::Known(0));
    // the R1 distinction itself, pinned: a measured zero is not an
    // inapplicable slot
    assert_ne!(Observed::Known(0), Observed::<u64>::NotApplicable);
    assert_eq!(counters.metadata_records_touched, Observed::NotApplicable);
    assert_eq!(counters.fallback_to_full_count, Observed::NotApplicable);
    assert_eq!(counters.restart_distance, Observed::NotApplicable);
    assert_eq!(counters.convergence_distance, Observed::NotApplicable);
    assert_eq!(
        counters.unique_post_source_bytes,
        Observed::Known(post.len() as u64)
    );
    // the measured nodes_reused zero survives finalize unchanged, and
    // the NotApplicable slots stayed NotApplicable through finalize
    assert_eq!(counters.nodes_reused, Observed::Known(0));
    assert_eq!(counters.metadata_records_touched, Observed::NotApplicable);
    // no slot is left Unknown after a completed, derived case
    assert!(!matches!(
        counters.unique_post_source_bytes,
        Observed::Unknown
    ));
}

