#[test]
#[ignore = "full 24-corpus x 13-recipe expansion; ~25 min in the debug profile — verify-r4.sh runs it with --release"]
fn structural_recipe_slots_reproduce_the_frozen_matrix_counts() {
    // The R4 instantiation must reproduce the frozen Block-D recipe-slot
    // expansion EXACTLY: every declared (shape, size, anchor) slot builds
    // an edit, and nothing outside the declared slots does. A scan that
    // finds no target where the matrix declares APPLICABLE, or an edit
    // where it declares NOT_APPLICABLE, fails here — and the 158-slot
    // total is checked against the manifest.
    use std::collections::BTreeMap;
    let mut counts: BTreeMap<&'static str, usize> = BTreeMap::new();
    for recipe in gen::mutations::ALL_RECIPES {
        counts.insert(recipe.id(), 0);
    }
    for size in [SIZE_64K, SIZE_1M, SIZE_16M] {
        for shape in ALL_SHAPES {
            let src = gen::generate(shape, size).expect("generate");
            for recipe in gen::mutations::ALL_RECIPES {
                let anchors: &[AnchorClass] = if recipe == Recipe::FsFenceOpen {
                    &[AnchorClass::Early, AnchorClass::Middle]
                } else {
                    &[recipe.selection_anchor()]
                };
                for &class in anchors {
                    if structural_edit_for(&src, recipe, class, shape, size).is_ok() {
                        *counts.get_mut(recipe.id()).expect("pre-inserted") += 1;
                    }
                }
            }
        }
    }
    const FROZEN: [(&str, usize); 13] = [
        ("M-LOC-TEXT", 12),
        ("M-LOC-UTF8-SWAP", 21),
        ("M-BB-PARA-SPLIT", 15),
        ("M-BB-PARA-MERGE", 17),
        ("M-CS-ITEM-INDENT", 6),
        ("M-CS-BQ-NEST-LINE", 6),
        ("M-FS-FENCE-OPEN", 42),
        ("M-FS-FENCE-CLOSE", 6),
        ("M-IDS-EMPH-INSERT", 6),
        ("M-IDS-CODE-DELIM", 6),
        ("M-IDS-LINK-DELIM", 9),
        ("M-SD-DEF-REPLACE", 6),
        ("M-SD-DEF-DELETE", 6),
    ];
    let mut total = 0;
    for (id, n) in FROZEN {
        assert_eq!(counts[id], n, "{id} slot count diverges from the freeze");
        total += n;
    }
    assert_eq!(total, 158, "frozen structural total");
}

#[test]
fn post_edit_states_satisfy_all_tree_invariants() {
    // Every structural edit applied to a 64k corpus must leave the H0
    // result inside the frozen tree invariants (validated again on the
    // post bytes, independently of the differential equality).
    for shape in ALL_SHAPES {
        let old = gen::generate(shape, SIZE_64K).expect("generate");
        for recipe in gen::mutations::ALL_RECIPES {
            if let Ok(edit) =
                structural_edit_for(&old, recipe, AnchorClass::Middle, shape, SIZE_64K)
            {
                let post = gen::mutations::apply(&old, &edit);
                let clean = validated_clean(&post);
                let state = mech_full_parse(&post);
                assert_eq!(state.document, clean, "{shape:?} {}", recipe.id());
            }
        }
    }
}

#[test]
fn container_depth_decrease_keeps_surviving_frames_open() {
    // Grammar §6/§7 continuation: a line that carries fewer container
    // prefixes closes only the frames whose prefix it FAILS; frames whose
    // prefix it carried stay open and own the re-dispatched content.
    // (Regression: an early strip_prefixes version re-examined
    // already-carried frames against the advanced column and cascaded the
    // close — surfaced by deep_container's descending mountains.)
    let bytes = b"> > b\n> c\n";
    let doc = h0::parse_document(bytes);
    validate_tree(&doc.root, bytes);
    let outer = &doc.root.children[0];
    assert_eq!(outer.kind, NodeKind::BlockQuote);
    assert_eq!((outer.start, outer.end), (0, 9)); // both quote lines
    assert_eq!(outer.children.len(), 2); // inner quote + the depth-1 para
    assert_eq!(outer.children[0].kind, NodeKind::BlockQuote);
    assert_eq!(outer.children[1].kind, NodeKind::Paragraph);
    assert_eq!((outer.children[1].start, outer.children[1].end), (8, 9));

    // a list item dedent inside a quote: the quote stays, the list closes
    let bytes = b"> - a\n> b\n";
    let doc = h0::parse_document(bytes);
    validate_tree(&doc.root, bytes);
    let outer = &doc.root.children[0];
    assert_eq!(outer.kind, NodeKind::BlockQuote);
    assert_eq!((outer.start, outer.end), (0, 9));
    assert_eq!(outer.children.len(), 2);
    assert_eq!(outer.children[0].kind, NodeKind::List);
    assert_eq!(outer.children[1].kind, NodeKind::Paragraph);
    assert_eq!((outer.children[1].start, outer.children[1].end), (8, 9));

    // sibling items still resolve through the parent list (§7 sibling rule)
    let bytes = b"- a\n  - b\n- c\n";
    let doc = h0::parse_document(bytes);
    validate_tree(&doc.root, bytes);
    let list = &doc.root.children[0];
    assert_eq!(list.kind, NodeKind::List);
    assert_eq!(list.children.len(), 2, "outer siblings");
    let nested = &list.children[0].children[1]; // [Para(a), List] source order
    assert_eq!(nested.kind, NodeKind::List);
    assert_eq!(nested.children.len(), 1);
}

#[test]
fn byte_coordinate_regression_probes() {
    // Small hand-built sources pinning byte-coordinate conventions the
    // corpora cannot isolate (NORMALIZED-RESULT-v1 span rules).
    let bytes = b"# h\n\ntext\n";
    let doc = h0::parse_document(bytes);
    validate_tree(&doc.root, bytes);
    let h = &doc.root.children[0];
    assert_eq!(h.kind, NodeKind::Heading);
    assert_eq!((h.start, h.end), (0, 3)); // excludes the LF

    let bytes = b"```rust\nlet x;\n```\n";
    let doc = h0::parse_document(bytes);
    validate_tree(&doc.root, bytes);
    let f = &doc.root.children[0];
    assert_eq!(f.kind, NodeKind::FencedCode);
    assert_eq!(f.start, 0);
    assert_eq!(f.end, 18); // closer line, LF excluded
    let (cs, ce) = f.content.expect("fence content");
    assert_eq!((cs, ce), (8, 15)); // raw body between the LFs

    let bytes = b"para\nEOF-no-newline";
    let doc = h0::parse_document(bytes);
    validate_tree(&doc.root, bytes);
    assert_eq!(doc.root.children.last().unwrap().end, 19); // no LF: to EOF

    let bytes = b"- a\n- b\n";
    let doc = h0::parse_document(bytes);
    validate_tree(&doc.root, bytes);
    let list = &doc.root.children[0];
    assert_eq!(list.kind, NodeKind::List);
    assert_eq!(list.children.len(), 2);
    assert!(list.children[0].end <= list.children[1].start); // source order
}
